{
  "claims": [
    {
      "claim": "Direct PET data with rifampicin in healthy baboons showed that rifampicin and its radiolabeled metabolites poorly penetrate the BBB, indicating limited CNS access after systemic administration.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-1"
      ]
    },
    {
      "claim": "In humans, after a 600 mg intravenous dose, rifampicin concentration in brain tissue resected around tumors was only 0.29 µg/mL, a low absolute brain concentration relative to systemic exposure and not convincing evidence of adequate CNS access.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-2"
      ]
    },
    {
      "claim": "The very close analogue rifapentine showed undetectable CSF (<0.15 mg/L) despite serum levels of 7.2 mg/L in patients, brain concentrations less than 20% of plasma in rats, and was judged not to cross the BBB to a quantitatively important extent; this strongly supports comparable failure for the rifampicin scaffold.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-2",
        "Record 11-4"
      ]
    },
    {
      "claim": "Other rifamycin analogues, rifamycin SV and rifamycin B, were classified as poor or impermeable across the BBB, indicating that the ansamycin backbone does not reliably provide meaningful CNS penetration.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 14",
        "Molecule 15"
      ],
      "record_ids": [
        "Record 14-2",
        "Record 14-3",
        "Record 15-1"
      ]
    },
    {
      "claim": "P-glycoprotein efflux is relevant to rifamycins: rifabutin showed an efflux ratio of 4.7 in MDCK-MDR1 cells and rifaximin is a P-gp substrate, so rifampicin-like molecules are expected to be subject to active efflux limiting brain exposure.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 21",
        "Molecule 23"
      ],
      "record_ids": [
        "Record 21-1",
        "Record 23-1",
        "Record 23-3"
      ]
    },
    {
      "claim": "Some rifampicin pharmacokinetic studies detected measurable brain concentrations in baboons, monkeys, and mice, showing that rifampicin is not completely excluded from the CNS.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-3",
        "Record 12-4",
        "Record 12-5"
      ]
    },
    {
      "claim": "Rifabutin, a related rifamycin, achieved more favorable CSF/plasma ratios and brain/plasma ratios in inflamed-meningitis models, suggesting some analogues can access the CNS when the BBB is disrupted; however, this does not overcome the direct poor-penetration data for rifampicin and rifapentine.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2",
        "Record 13-6"
      ]
    }
  ],
  "final_prediction": "fail"
}

